(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('auto-tag-mod', {
    meta: {
      name: 'Auto-Tag Mod',
      type: 'Mod',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Automatically add tags to cards based on content keywords'
    },

    // Tag rules: pattern -> tag
    tagRules: [
      { pattern: /\b(bug|issue|error|problem|fix)\b/i, tag: 'bug' },
      { pattern: /\b(todo|task|action item)\b/i, tag: 'todo' },
      { pattern: /\b(question|\?|how|why|what)\b/i, tag: 'question' },
      { pattern: /\b(idea|brainstorm|concept)\b/i, tag: 'idea' },
      { pattern: /\b(meeting|discussion)\b/i, tag: 'meeting' },
      { pattern: /\b(urgent|asap|critical|important)\b/i, tag: 'urgent' },
      { pattern: /\b(project|initiative)\b/i, tag: 'project' },
      { pattern: /\b(research|study|analysis)\b/i, tag: 'research' }
    ],

    async onCardSave(ctx, card, saveInfo) {
      // Only process if content changed
      if (!saveInfo.isNew && !this.contentChanged(saveInfo)) {
        return;
      }

      const content = `${card.title} ${card.body}`.toLowerCase();
      const currentTags = card.tags || [];
      let tagsAdded = [];

      // Check each rule
      for (const rule of this.tagRules) {
        if (rule.pattern.test(content)) {
          if (!currentTags.includes(rule.tag)) {
            const added = await ctx.utils.addTag(card.id, rule.tag);
            if (added) {
              tagsAdded.push(rule.tag);
              ctx.logger.log(`Auto-tagged card ${card.id} with #${rule.tag}`);
            }
          }
        }
      }

      if (tagsAdded.length > 0) {
        ctx.utils.showToast(
          `Auto-tagged: ${tagsAdded.map(t => '#' + t).join(', ')}`,
          'info'
        );
      }
    },

    contentChanged(saveInfo) {
      if (!saveInfo.previousData) return false;
      return (
        saveInfo.previousData.title !== undefined ||
        saveInfo.previousData.body !== undefined
      );
    },

    onAppInit(ctx) {
      ctx.logger.log('Auto-Tag Mod initialized with', this.tagRules.length, 'rules');
    }
  });
})();
